  "contact.intro": "Proje hakkında sorular, kayıtlar veya iş birliği talepleri — mesajınızı bekliyoruz.",
  "contact.org_label": "Yürütücü kuruluş", "contact.address_label": "Adres", "contact.phone_label": "Telefon", "contact.email_label": "E-posta",
